            忽略指定类或方法的 MiniAPI 生成（运行时生效，替代原 [IgnoreMiniApi] 特性）。


            源生成器（MiniApiGenerator/OpenApiGenerator）检测到本调用后，会为被忽略的类/方法
            生成带运行时判断的代码：仅当  返回 false 时才注册端点/输出 OpenAPI。
            支持两种传参格式：


IgnoreMiniApi("Test.UserService.GetAll")：忽略该类下指定方法（接口）的 MiniAPI 生成。

IgnoreMiniApi("Test.UserService")：忽略该类下所有方法（接口）的 MiniAPI 生成。

            典型用法（按配置决定是否启用接口）：

            if (setting != null && setting.MiniprogramOption != null && setting.MiniprogramOption.Any())
            {
                cyberSetting.AddHttpClient<IMiniprogramApi>(http => { http.HttpHost = url; });
            }
            else
            {
                cyberSetting.IgnoreMiniApi("Test.UserService");
            }

             标记类或记录类型需要由 Cyber.Json 源生成器自动生成 JsonConverter 和 JsonTypeInfo。


             与官方 JsonSerializableAttribute 的区别：不依赖 JsonSerializerContext，
             由 Cyber.Json 源生成器直接识别，避免官方源生成器的 SYSLIB1224 警告。



             规则：
             1. 不传参数（[JsonGenerate]）：仅标记声明类自身生成 Converter / JsonTypeInfo。
             2. 传类型参数（[JsonGenerate(typeof(List<T>))]）：为 List<T>、IEnumerable<T>、
                Dictionary<K, V> 等聚合类型生成对应类型的 Converter；元素类型 / 字典值类型必须与声明类一致。
             3. 可以添加多个，每个参数生成一个该类型的 Converter。


使用示例：

             [JsonGenerate]
             public class UserInfo
             {
                 public long UserId { get; set; }
             }

             [JsonGenerate(typeof(List<Order>))]
             [JsonGenerate(typeof(Dictionary<string, Order>))]
             public class Order
             {
                 public string OrderNo { get; set; }
             }

标记 JsonConverter<T> 类为全局转换器。


设置后，该转换器对目标类型 T 的所有引用位置（属性、可空属性、集合元素、字典值、元组元素）
自动生效，无需在属性上逐个添加 [JsonConverter]。



使用示例：

[JsonGlobalConverter]
public class UpperStringConverter : JsonConverter<string>
{
    public override string Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        => (reader.GetString() ?? "").ToUpperInvariant();

    public override void Write(Utf8JsonWriter writer, string value, JsonSerializerOptions options)
        => writer.WriteStringValue(value?.ToLowerInvariant());
}



之后所有序列化实体中的 string 属性都会自动使用该转换器。
目标类型 T 从基类 JsonConverter<T> 的泛型参数自动推断。
优先级：属性级 [JsonConverter] > 全局 [JsonGlobalConverter] > 默认逻辑。

CSV 导出门面：[ExportFile(ExportFormat.Csv)] 端点统一返回 Stream 的构建入口。



[ExportFile(ExportFormat.Csv, FileName = "orders_{tenant}.csv")]
public Stream ExportCsv(int rows = 10)
    => CyberExportCSV.From(ct => Db.Queryable<Order>().ToEnumerableAsync(ct))
        .Column("订单号", r => r.OrderId)
        .ToStream();

remarks.code:
public class TokenModel : IdentityUser<TokenModel>
{
    public long UserId { get; set; }
    public string UserName { get; set; }
    public string Role { get; set; }

    public TokenModel GetIdentityUser(
        IdentityUserContext ctx,
        TokenModel token)
    {
        // 可通过 ctx 访问请求上下文
        var logger = ctx.RequestServices
            .GetService<ILogger<TokenModel>>();

        logger?.LogInformation(
            "用户 {UserId} 访问方法 {Method}",
            token.UserId,
            ctx.MethodName);

        // 方法级权限判断
        if (ctx.MethodName == "DeleteUser" 
            && token.Role != "Admin")
        {
            throw new UnauthorizedException(
                "只有管理员可以删除用户");
        }

        // 可从数据库加载更完整的用户信息
        var dbContext = ctx.RequestServices
            .GetService<MyDbContext>();

        var fullUser = dbContext?
            .Users
            .Find(token.UserId);

        if (fullUser != null)
        {
            token.UserName = fullUser.UserName;
            token.Role = fullUser.Role;
        }

        return token;
    }
}
[JwtAuthorize]
[MiniApi("api/user")]
public class UserController : MiniApiController<TokenModel>
{
    public void GetProfile()
    {
        var userId = CurrentUser.UserId;
        var userName = CurrentUser.UserName;
    }

}

// 对于 [JwtAuthorize("Admin")]
{
    ["Key"] = "Admin"
}

// 对于 [MiniApi("api/user", Tag = "用户管理")]
{
    ["RoutePrefix"] = "api/user",
    ["Tag"] = "用户管理"
}

public TokenModel GetIdentityUser(IdentityUserContext ctx, TokenModel token)
{
    if (ctx.MethodName == "DeleteUser" && token.Role != "Admin")
    {
        throw new UnauthorizedException("只有管理员可以删除用户");
    }
    return token;
}

public TokenModel GetIdentityUser(IdentityUserContext ctx, TokenModel token)
{
    if (ctx.JwtAuthorizeKey == "Admin")
    {
        // 管理员认证配置的额外验证
    }
    return token;
}

public TokenModel GetIdentityUser(IdentityUserContext ctx, TokenModel token)
{
    // 查找控制器上的特定特性
    var jwtAttr = ctx.ControllerAttributes.FirstOrDefault(a => a.AttributeName == "JwtAuthorizeAttribute");
    if (jwtAttr != null)
    {
        var key = jwtAttr.Properties.TryGetValue("Key", out var k) ? k : null;
        // 根据 Key 进行不同的权限验证
    }

    // 查找自定义权限特性
    var permissionAttr = ctx.ControllerAttributes.FirstOrDefault(a => a.AttributeName == "RequirePermissionAttribute");
    if (permissionAttr != null)
    {
        var requiredPermission = permissionAttr.Properties["Permission"];
        if (!token.Permissions.Contains(requiredPermission))
        {
            throw new UnauthorizedException($"需要 {requiredPermission} 权限");
        }
    }

    return token;
}

public TokenModel GetIdentityUser(IdentityUserContext ctx, TokenModel token)
{
    // 方法级别的权限特性优先
    var methodJwtAttr = ctx.MethodAttributes.FirstOrDefault(a => a.AttributeName == "JwtAuthorizeAttribute");
    if (methodJwtAttr != null)
    {
        // 使用方法级别的认证配置
    }

    // 检查方法是否允许匿名访问
    var allowAnon = ctx.MethodAttributes.Any(a => a.AttributeName == "AllowAnonymousAttribute");
    if (allowAnon)
    {
        // 匿名方法不验证权限
        return token;
    }

    // 查找方法上的角色要求特性
    var roleAttr = ctx.MethodAttributes.FirstOrDefault(a => a.AttributeName == "RequireRoleAttribute");
    if (roleAttr != null)
    {
        var requiredRole = roleAttr.Properties["Role"];
        if (token.Role != requiredRole)
        {
            throw new UnauthorizedException($"需要 {requiredRole} 角色");
        }
    }

    return token;
}

member.summary:
按区分键值定向清除该端点的输出缓存：只清命中该值的缓存项，其他变体保留。
参数就是 KeyGenerator 产出的区分键值，不需要也不接受完整缓存 Key （端点由 CacheOutput.XXX 确定，路径/查询串不参与匹配）。命中规则：
// 规则类按 category 区分（区分键 = category 的值）： CacheOutput.GetByCategory.Clear("books"); // 只清 books 分类的缓存
// 组合区分键（多维度以 "|" 拼接，如 "u{UserID}|{category}"）： CacheOutput.GetPerUserTenant.Clear("u1001|t1"); // 完整值：只清用户 1001 的 t1 CacheOutput.GetPerUserTenant.Clear("t1"); // 维度值：清掉所有用户的 t1
传空串匹配「未配置 KeyGenerator / 委托返回空串」产生的那份共享缓存。

remarks.code:
[MiniApi("api/user")]
public class UserController : MiniApiController
{
    public string Get()
    {
        // 访问 HttpContext
        var headers = HttpContext.Request.Headers;
        return "header";
    }
}

// 1. 定义用户身份实体
public class TokenModel : IdentityUser<TokenModel>
{
    public long UserId { get; set; }
    public string UserName { get; set; }

    public TokenModel GetIdentityUser(IServiceProvider services, TokenModel token)
    {
        // 可从数据库加载更多信息
        return token;
    }
}

// 2. 创建控制器
[JwtAuthorize]  // 必须标记此特性才会自动注入 CurrentUser
[MiniApi("api/order")]
public class OrderController : MiniApiController<TokenModel>
{
    public IActionResult GetMyOrders()
    {
        // 直接访问 CurrentUser 获取当前用户信息
        var userId = CurrentUser.UserId;
        var orders = _orderService.GetByUserId(userId);
        return Ok(orders);
    }

    [AllowAnonymous]  // 匿名方法不会注入 CurrentUser
    public IActionResult GetPublicInfo()
    {
        return Ok();
    }
}

var __instance = __sp.GetRequiredService<OrderController>();
__instance.HttpContext = ctx;

// JWT Token 解析和 CurrentUser 注入
var __currentUserToken = Cyber.AuthHelper.GetTokenFromHeader(ctx, "");
if (!string.IsNullOrEmpty(__currentUserToken))
{
    var __authOptions = __sp.GetService<Cyber.AuthOptions>();
    var __decodeResult = Cyber.AuthHelper.DecodeToken<TokenModel>(__currentUserToken, __authOptions.Security, JsonTypeInfo);
    if (__decodeResult.IsValid && __decodeResult.Entity != null)
    {
        __instance.CurrentUser = __decodeResult.Entity.GetIdentityUser(__sp, __decodeResult.Entity);
    }
}

