await ReTry
    .Do(async (retryCount) =>
    {
        Console.WriteLine($"第 {retryCount} 次尝试");
        await DoSomethingAsync();
    })
    .WithOptions(opt => opt.Attempts = 3)
    .ExecuteAsync();

var result = await ReTry
    .Do(async (count) =>
    {
        Console.WriteLine($"第 {count} 次请求");
        return await GetDataAsync();
    })
    .WithOptions(opt => opt.Attempts = 5)
    .ExecuteAsync();

var result = ReTry
    .Do((count) =>
    {
        Console.WriteLine($"第 {count} 次执行获取结果");
        return GetData();
    })
    .WithOptions(opt => opt.Attempts = 3)
    .Execute();

